    '<div class="pane" style="flex:none"><div class="pane-h"><b>Errors</b><span class="sub">grouped by bill and code</span><span class="spacer"></span><div class="tabs">'+chips+'</div></div><div class="cards">'+cards+'</div></div></div>';
}

