    '<span class="sev"><i style="background:'+sevCol(g.maxSev)+'"></i>'+g.maxSev+'</span>'+
    (g.rows.length>1?'<span class="chip">'+g.rows.length+' blocks</span>':'')+'</div><div class="c2">'+esc(codeName(g))+'</div>'+
    '<div class="c3">Bill '+esc(g.bill_id||"—")+' · invoice '+esc(fmtD(day(g.invoice_d)))+' · '+esc(g.account||"")+'</div></div>';
