function statusChip(g){ var m={open:["st-open","Open"],ack:["st-ack","Acknowledged"],flag:["st-flag","Flagged"],res:["st-res","Resolved"]}[g.status]; return '<span class="chip '+m[0]+'">'+m[1]+'</span>'; }

function chartHtml(its,here){
  var comms=commodities(its);
  var ctabs=comms.map(function(c){ var n=here.filter(function(g){ return g.rows.some(function(r){ return String((r._d||{}).commodity||"").toUpperCase()===c; }); }).length;
    return '<button class="tab'+(S.commodity===c?" on":"")+'" data-comm="'+esc(c)+'">'+esc(c)+(n?'<span class="n">'+n+'</span>':'')+'</button>'; }).join("");
  var pts=series(its), u=S.unit;
  var utabs=UNITS.map(function(x){ var n=here.filter(function(g){ return CHART_UNIT[g.code]===x[0]; }).length;
    return '<button class="tab'+(u===x[0]?" on":"")+'" data-unit="'+x[0]+'">'+x[1]+(n?'<span class="n">'+n+'</span>':'')+'</button>'; }).join("");
  var W=Math.max(420,(document.getElementById("root").clientWidth||1000)*0.6-60), H=230, L=62, R=14, T=12, B=26, LANE=34;
  var now=Date.now(), from=now-(Number(M.months)||12)*30.44*DAY;
  var inWin=pts.filter(function(p){ return p.e>=from; });
  var x0=Math.min(from, inWin.length?inWin[0].s:from), x1=now;
  var X=function(t){ return L+(t-x0)/(x1-x0)*(W-L-R); };
  var vals=inWin.map(function(p){ return p.v[u]; }).filter(function(v){ return v!=null; });
  var ymax=vals.length?Math.max.apply(null,vals)*1.12:1; if(!(ymax>0)) ymax=1;
  var Y=function(v){ return T+(1-v/ymax)*(H-T-B); };
  var uom=(inWin.filter(function(p){return p.uom;})[0]||{}).uom||"";
  var svg='<svg width="'+W+'" height="'+(H+LANE+18)+'">';
  for(var k=0;k<=4;k++){ var yv=ymax*k/4, yy=Y(yv); svg+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+yy+'" y2="'+yy+'" stroke="#1f3346"/><text x="'+(L-6)+'" y="'+(yy+4)+'" text-anchor="end">'+esc(shortV(yv,u))+'</text>'; }
  var d0=new Date(x0); for(var mth=new Date(Date.UTC(d0.getUTCFullYear(),d0.getUTCMonth()+1,1)).getTime(); mth<x1; ){ var dm=new Date(mth); if(dm.getUTCMonth()%3===0) svg+='<text x="'+X(mth)+'" y="'+(H-8)+'" text-anchor="middle">'+["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][dm.getUTCMonth()]+" "+String(dm.getUTCFullYear()).slice(2)+'</text>'; mth=Date.UTC(dm.getUTCFullYear(),dm.getUTCMonth()+1,1); }
  // error lookup per point
  var chartGs=here.filter(function(g){ return g.place==="chart"; });
  var marks=inWin.map(function(p){ return chartGs.filter(function(g){ return p.records[g.record_id]; }); });
  // bands first, then line, then points
  inWin.forEach(function(p,i){
    var on=marks[i].filter(function(g){ return CHART_UNIT[g.code]===u; });
    if(on.length) svg+='<rect x="'+X(Math.max(p.s,x0))+'" y="'+T+'" width="'+Math.max(3,X(p.e)-X(Math.max(p.s,x0))-2)+'" height="'+(H-T-B)+'" fill="'+COL.band+'" fill-opacity=".06"/>';
  });
  var path=""; inWin.forEach(function(p){ var v=p.v[u]; if(v==null) return; path+=(path?"L":"M")+X(p.m).toFixed(1)+","+Y(v).toFixed(1); });
  if(path) svg+='<path d="'+path+'" fill="none" stroke="'+COL.line+'" stroke-width="2"/>';
  inWin.forEach(function(p,i){
    var v=p.v[u], on=marks[i].filter(function(g){ return CHART_UNIT[g.code]===u; }), off=marks[i].filter(function(g){ return CHART_UNIT[g.code]!==u; });
    var pv=p.prior?p.prior.v[u]:null, pct=(v!=null&&pv)?((v-pv)/Math.abs(pv)*100):null;
    var base="Bill "+(p.bill_id||"—")+"  ·  "+fmtD(p.s)+" – "+fmtD(p.e)+"\n"+UNITS.filter(function(x){return x[0]===u;})[0][1]+": "+fmtV(v,u,p.uom)+(pv!=null?"\nPrior bill: "+fmtV(pv,u,p.prior.uom)+(pct!=null?"  ("+(pct>=0?"+":"")+pct.toFixed(0)+"%)":""):"");
    if(v!=null){
      if(on.length){
        if(p.prior&&pv!=null) svg+='<circle cx="'+X(p.prior.m)+'" cy="'+Y(pv)+'" r="7" fill="none" stroke="'+COL.prior+'" stroke-dasharray="3 2"/>';
        var tip=base+"\n\n"+on.map(function(g){ return g.code+"  "+codeName(g)+"  ["+g.status+"]"; }).join("\n")+"\nClick to review";
        var ms=Math.max.apply(null,on.map(function(g){return g.maxSev;}));
        svg+='<circle class="hot" cx="'+X(p.m)+'" cy="'+Y(v)+'" r="6" fill="'+sevCol(ms)+'" stroke="#132230" stroke-width="2" data-pop="'+esc(on.map(function(g){return g.key;}).join(","))+'" data-tip="'+esc(tip)+'"/>';
      } else svg+='<circle cx="'+X(p.m)+'" cy="'+Y(v)+'" r="3.5" fill="'+COL.line+'" data-tip="'+esc(base)+'"/>';
    }
    if(off.length) svg+='<rect class="hot" x="'+(X(p.m)-2)+'" y="'+(H-B)+'" width="4" height="7" fill="'+sevCol(Math.max.apply(null,off.map(function(g){return g.maxSev;})))+'" fill-opacity=".7" data-pop="'+esc(off.map(function(g){return g.key;}).join(","))+'" data-tip="'+esc(off.map(function(g){ return g.code+"  "+codeName(g)+"  (switch to "+UNITS.filter(function(x){return x[0]===CHART_UNIT[g.code];})[0][1]+")"; }).join("\n"))+'"/>';
  });
  // timeline lane
  var ly=H+6;
  svg+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+(ly+LANE/2)+'" y2="'+(ly+LANE/2)+'" stroke="#1f3346"/><text x="'+(L-6)+'" y="'+(ly+LANE/2+4)+'" text-anchor="end">Dates</text>';
  var commIts=its.filter(function(i){ return i.comm===S.commodity; });
  var lost=0;
  here.filter(function(g){ return g.place==="timeline"; }).forEach(function(g){
    var r=timelineRange(g,commIts); if(!r){ lost++; return; }
    if(r.e<x0) return;
    var warn=g.code===3009||g.code===3011;
    var xa=X(Math.max(r.s,x0)), xb=X(r.e+DAY);
    var tip=g.code+"  "+codeName(g)+"  (severity "+g.maxSev+")\n"+fmtD(r.s)+" – "+fmtD(r.e)+"  ("+Math.round((r.e-r.s)/DAY+1)+" days, "+r.how+")"+
      (r.before?"\nBefore: bill "+(r.before.bill_id||"—")+"  "+fmtD(r.before.s)+" – "+fmtD(r.before.e):"")+
      (r.after&&r.after!==r.before?"\nAfter: bill "+(r.after.bill_id||"—")+"  "+fmtD(r.after.s)+" – "+fmtD(r.after.e):"")+"\nClick to review";
    svg+='<rect class="hot" x="'+xa+'" y="'+(ly+8)+'" width="'+Math.max(4,xb-xa)+'" height="'+(LANE-16)+'" rx="3" fill="'+(g.status==="flag"?COL.flag:(warn?COL.sev.w:sevCol(g.maxSev)))+'" fill-opacity="'+(g.status==="open"||g.status==="flag"?".85":".3")+'" data-pop="'+esc(g.key)+'" data-tip="'+esc(tip)+'"/>';
  });
  svg+='</svg>';
  var noData=vals.length?"":'<div class="empty" style="padding:6px">No '+esc(UNITS.filter(function(x){return x[0]===u;})[0][1].toLowerCase())+' values on these bills'+(u==="demand"||u==="lf"?" (no matching calculation found)":"")+'.</div>';
  return '<div class="chartbox"><div class="tabs" style="margin-bottom:6px">'+ctabs+'<span class="spacer" style="flex:1"></span>'+utabs+'</div>'+svg+noData+'</div>'+
    '<div class="leg"><span><i style="background:'+COL.line+'"></i>'+esc(S.commodity||"")+' '+esc(uom)+' per bill</span><span><i style="background:rgba(231,238,244,.14)"></i>Bill with an error</span><span><i style="border:1px dashed '+COL.prior+'"></i>Prior bill</span>'+
    '<span><i style="background:'+COL.sev.c+';border-radius:50%"></i>Severity \u226560</span><span><i style="background:'+COL.sev.s+';border-radius:50%"></i>40\u201359</span><span><i style="background:'+COL.sev.w+';border-radius:50%"></i>Below 40 / warning</span><span><i style="background:'+COL.flag+'"></i>Flagged</span>'+(lost?'<span>'+lost+' date error(s) not on this commodity</span>':'')+'</div>';
}
function shortV(v,u){ if(u==="$") return "$"+(v>=1e6?(v/1e6).toFixed(1)+"M":v>=1e3?(v/1e3).toFixed(0)+"k":v.toFixed(0)); if(u==="unit") return "$"+v.toFixed(3); if(u==="lf") return (v>1.5?v.toFixed(0):(v*100).toFixed(0))+"%"; return v>=1e6?(v/1e6).toFixed(1)+"M":v>=1e3?(v/1e3).toFixed(0)+"k":v.toFixed(0); }

function popupHtml(gs){
  if(!S.popup) return "";
  var keys=S.popup, list=gs.filter(function(g){ return keys.indexOf(g.key)>=0; });
  if(!list.length){ S.popup=null; return ""; }
  var its=items();
  var body=list.map(function(g){
    var todo=TODO[g.code]||"either";
    var msgs={}; g.rows.forEach(function(r){ if(r.message) msgs[r.message]=true; });
    var ml=Object.keys(msgs);
    var kv=[["Stage",stageLbl(g.stage)],["Severity",g.rows.map(function(r){return r.severity;}).filter(function(v,i,a){return a.indexOf(v)===i;}).join(", ")],
      ["Bill",(g.bill_id||"—")+"  ·  invoice "+fmtD(day(g.invoice_d))],["Account",g.account||"—"],["Vendor",g.vendor||"—"]];
