    if(mine.length){ var s=Math.min.apply(null,mine.map(function(i){return i.s;})), e=Math.max.apply(null,mine.map(function(i){return i.e||i.s;})); kv.push(["Service period",fmtD(s)+" – "+fmtD(e)]); }
