      s:day(b.start_d), e:day(b.end_d), inv:b.invoice_d, charges:num(b.charges), total:num(b.bill_total), usage:num(b.usage), uom:b.uom,
      demand:calcVal(b.calcs,/demand/i,/charge|cost|rate|\$/i), lf:calcVal(b.calcs,/load.?factor/i)};
  }).filter(function(i){ return i.s!=null; });
}
function commodities(its){ var c={}; its.forEach(function(i){ if(i.comm) c[i.comm]=(c[i.comm]||0)+1; }); return Object.keys(c).sort(function(a,b){ return (b==="ELECTRIC")-(a==="ELECTRIC") || c[b]-c[a]; }); }
function series(its){
  var by={}, pts=[];
  its.filter(function(i){ return i.comm===S.commodity; }).forEach(function(i){
    var p=by[i.bill]; if(!p){ p=by[i.bill]={bill:i.bill,bill_id:i.bill_id,records:{},s:i.s,e:i.e,inv:i.inv,charges:null,total:null,usage:null,uom:i.uom,demand:null,lf:null}; pts.push(p); }
    p.records[i.record]=true; p.s=Math.min(p.s,i.s); if(i.e!=null) p.e=Math.max(p.e||i.e,i.e);
    if(i.charges!=null) p.charges=(p.charges||0)+i.charges;
    if(i.total!=null&&p.total==null) p.total=i.total;
    if(i.usage!=null) p.usage=(p.usage||0)+i.usage;
    if(i.demand!=null) p.demand=Math.max(p.demand||0,i.demand);
    if(i.lf!=null) p.lf=i.lf;
  });
  pts.forEach(function(p){ if(p.e==null) p.e=p.s; p.m=(p.s+p.e)/2; var c=p.charges!=null?p.charges:p.total;
    p.v={"$":c, usage:p.usage, demand:p.demand, lf:p.lf, unit:(c!=null&&p.usage)?c/p.usage:null}; });
  pts.sort(function(a,b){ return a.s-b.s; });
  pts.forEach(function(p,i){ p.prior=i>0?pts[i-1]:null; });
  return pts;
}
// service-date ranges come from the neighbouring bill on the same account
function timelineRange(g,its){
  var kind=TIMELINE[g.code], out=null;
  Object.keys(g.va).forEach(function(va){
    var mine=its.filter(function(i){ return String(i.va)===String(va); }).sort(function(a,b){ return a.s-b.s; });
    mine.forEach(function(it,idx){
      if(String(it.record)!==String(g.record_id)||out) return;
      var prev=idx>0?mine[idx-1]:null, next=idx<mine.length-1?mine[idx+1]:null;
      if(kind==="gap"&&prev&&prev.e!=null&&it.s-prev.e>DAY) out={s:prev.e+DAY,e:it.s-DAY,before:prev,after:it,how:"computed"};
      else if(kind==="gap"&&next&&it.e!=null&&next.s-it.e>DAY) out={s:it.e+DAY,e:next.s-DAY,before:it,after:next,how:"computed"};
      else if(kind==="overlap"&&prev&&prev.e!=null&&prev.e>=it.s) out={s:it.s,e:prev.e,before:prev,after:it,how:"computed"};
      else if(kind==="overlap"&&next&&it.e!=null&&it.e>=next.s) out={s:next.s,e:it.e,before:it,after:next,how:"computed"};
      else out={s:it.s,e:it.e!=null?it.e:it.s,before:prev,after:it,how:kind==="read"?"period":"period (neighbour not found)"};
    });
  });
  return out;
}

// ---- outgoing events ----------------------------------------------------------
// The value travels as the event payload (a variable in the handler) and is
// also written to the model as a fallback; the model alone can be reset
// before the handler reads it.
function send(ev,patch){ appsmith.updateModel(patch); appsmith.triggerEvent(ev,patch); }

// ---- render -------------------------------------------------------------------
function render(){
  var root=document.getElementById("root"); if(!root) return;
  var keepScroll={}; Array.prototype.forEach.call(root.querySelectorAll("[data-keep]"),function(el){ keepScroll[el.getAttribute("data-keep")]=el.scrollTop; });
  var sum=summaryByLoc();
  var gs=groups(), vs=selVas();
  var shown=gs.filter(visible);
  root.innerHTML='<div class="app">'+topBar()+'<div class="main">'+leftPane(sum,gs)+rightPane(gs,shown,vs)+'</div></div>'+popupHtml(gs);
  Array.prototype.forEach.call(root.querySelectorAll("[data-keep]"),function(el){ var k=el.getAttribute("data-keep"); if(keepScroll[k]) el.scrollTop=keepScroll[k]; });
  bind();
}

function topBar(){
  var opts='<option value="">Select a customer…</option>'+(M.customers||[]).map(function(c){ return '<option value="'+esc(c.id)+'"'+(String(c.id)===String(M.customerId)?" selected":"")+'>'+esc(c.name)+'</option>'; }).join("");
  var mo=[6,12,24].map(function(n){ return '<option value="'+n+'"'+(Number(M.months)===n?" selected":"")+'>Last '+n+' months</option>'; }).join("");
  return '<div class="bar"><h1>Error Explorer</h1><span class="pill" data-tip="Acknowledge and Flag are kept in this browser tab only. Nothing is written to UBM until the backend endpoints exist.">Prototype · actions not saved</span>'+
    '<label>Customer <select id="cust">'+opts+'</select></label><label><select id="months">'+mo+'</select></label>'+
    '<span class="spacer"></span>'+
    '<button class="tog'+(S.all?" on":"")+'" id="all"><span class="sw"></span>All errors</button>'+
    '<button class="tog'+(S.muted?" on":"")+'" id="muted"><span class="sw"></span>Show acknowledged / resolved</button></div>';
}

function leftPane(sum,gs){
  var body;
  if(!M.customerId) body='<div class="empty">Pick a customer to load its locations.</div>';
  else if(M.locationsLoading) body='<div class="empty">Loading locations…</div>';
  else {
    var q=S.q.toLowerCase();
    var allLocs=M.locations||[]; if(allLocs.length&&String(allLocs[0].cust)!==String(M.customerId)) allLocs=[];
    var locs=allLocs.filter(function(l){ return !q || (String(l.name)+" "+(l.addr||"")+" "+(l.city||"")+" "+l.location_id).toLowerCase().indexOf(q)>=0; });
    locs.sort(function(a,b){ return ((sum[b.location_id]||{}).n||0)-((sum[a.location_id]||{}).n||0) || String(a.name).localeCompare(String(b.name)); });
    var html="";
    var none=sum.none;
    if(none&&S.all) html+='<div class="row muted" data-tip="These errors are on bill blocks that are not mapped to any location (e.g. 3018), so they cannot be placed in the tree."><span class="caret"></span><span class="dot sev-'+sevKey(none.sev)+'"></span><span class="lbl"><div class="t">Unmapped bills</div><div class="s">No location to attach to</div></span><span class="cnt num">'+none.n+'</span></div>';
    locs.slice(0,400).forEach(function(l){
      var id=String(l.location_id), s=sum[id], sel=String(M.locationId)===id, n=s?s.n:0;
      var tip=s?("Highest severity "+s.sev+"\n")+Object.keys(s.codes).sort().map(function(c){ return c+"  "+(NAMES[c]||"")+"  ×"+s.codes[c]; }).join("\n"):"";
      html+='<div class="row'+(sel&&!S.sel?" sel":"")+'" data-loc="'+esc(id)+'"'+(tip?' data-tip="'+esc("Open errors\n"+tip)+'"':"")+'>'+
        '<span class="caret">'+(sel?"▼":"▶")+'</span><span class="dot'+(n&&S.all?" sev-"+sevKey(s.sev):" off")+'"></span>'+
        '<span class="lbl"><div class="t">'+esc(l.name)+'</div><div class="s">'+esc([l.btype,l.addr,l.city,l.state].filter(Boolean).join(" · "))+'</div></span>'+
        (n&&S.all?'<span class="cnt num">'+n+'</span>':'')+'</div>';
      if(sel) html+=accountRows(gs);
    });
    if(locs.length>400) html+='<div class="empty">Showing 400 of '+locs.length+' locations. Narrow with search.</div>';
    if(!locs.length) html+='<div class="empty">No locations match.</div>';
    body=html;
  }
  var loadingSum = M.summaryLoading?'<span class="sub">counting errors…</span>':'';
  return '<div class="pane"><div class="pane-h"><b>Locations</b>'+loadingSum+'<span class="spacer"></span><input type="text" id="q" placeholder="Search" value="'+esc(S.q)+'" style="width:150px"></div><div class="scroll" data-keep="tree">'+body+'</div></div>';
}

function rowErr(gs,test){
  var dots=[], other=0, sev=0;
  gs.forEach(function(g){ if(!visible(g)||!test(g)) return; if(g.place==="dot"){ dots.push(g.key); sev=Math.max(sev,g.maxSev); } else other++; });
  return {dots:dots,other:other,sev:sev};
}
function accountRows(gs){
  if(M.detailLoading) return '<div class="row l1 muted"><span class="lbl">Loading accounts…</span></div>';
  var t=tree(); if(!t.length) return '<div class="row l1 muted"><span class="lbl">No accounts paired to this location.</span></div>';
  return t.map(function(a){
    var set={}; a.vas.forEach(function(v){ set[v.va_id]=true; });
    var e=rowErr(gs,function(g){ return inSel(g,set); });
    var open=!!S.expanded[a.key], sel=S.sel&&S.sel.kind==="acct"&&S.sel.acct===a.key;
    var h='<div class="row l1'+(sel?" sel":"")+'" data-acct="'+esc(a.key)+'">'+
      '<span class="caret" data-exp="'+esc(a.key)+'">'+(open?"▼":"▶")+'</span>'+
      (e.dots.length?'<span class="dot hot sev-'+sevKey(e.sev)+'" data-pop="'+esc(e.dots.join(","))+'" data-tip="'+esc(e.dots.length+" account-level error(s), click to review")+'"></span>':'<span class="dot off"></span>')+
      '<span class="lbl"><div class="t">'+esc(a.key)+'</div><div class="s">'+esc([a.vendor,Object.keys(a.comms).join(", ")].filter(Boolean).join(" · "))+'</div></span>'+
      (e.other?'<span class="cnt num" data-tip="Other open errors on this account">'+e.other+'</span>':'')+'</div>';
    if(open) a.vas.forEach(function(v){
      var one={}; one[v.va_id]=true;
      var em=rowErr(gs,function(g){ return inSel(g,one); });
      var msel=S.sel&&S.sel.kind==="meter"&&String(S.sel.va)===String(v.va_id);
      h+='<div class="row l2'+(msel?" sel":"")+'" data-va="'+esc(v.va_id)+'" data-acctof="'+esc(a.key)+'"><span class="caret"></span>'+
        (em.dots.length?'<span class="dot hot sev-'+sevKey(em.sev)+'" data-pop="'+esc(em.dots.join(","))+'"></span>':'<span class="dot off"></span>')+
        '<span class="lbl"><div class="t">'+esc(v.meter_serial||"No meter id")+'</div><div class="s">'+esc([v.commodity,v.client_account,v.closed?"Closed":""].filter(Boolean).join(" · "))+'</div></span>'+
        (em.other?'<span class="cnt num">'+em.other+'</span>':'')+'</div>';
    });
    return h;
  }).join("");
}

function rightPane(gs,shown,vs){
  if(!M.locationId) return '<div class="pane"><div class="empty" style="margin:auto">Select a location to see its chart, timeline and errors.</div></div>';
  var loc=(M.locations||[]).filter(function(l){ return String(l.location_id)===String(M.locationId); })[0]||{};
  var scope = !S.sel ? "Whole location" : (S.sel.kind==="acct" ? "Account "+S.sel.acct : "Meter "+(S.sel.label||S.sel.va));
  var its=items(), comms=commodities(its);
  if(comms.indexOf(S.commodity)<0) S.commodity=comms[0]||null;
  var here=shown.filter(function(g){ return inSel(g,vs); });
  var head='<div class="pane-h"><b>'+esc(loc.name||("Location "+M.locationId))+'</b><span class="sub">'+esc(scope)+'</span><span class="spacer"></span>'+
    (S.sel?'<button class="btn" id="clearsel">Show whole location</button>':'')+'</div>';
  var chart;
  if(M.detailLoading) chart='<div class="empty">Loading bills and errors…</div>';
  else if(!comms.length) chart='<div class="empty">No bills in this window for '+esc(scope.toLowerCase())+'.</div>';
  else chart=chartHtml(its,here);
  var chips=["all","card","chart","timeline","dot"].map(function(p){ var n=p==="all"?here.length:here.filter(function(g){return g.place===p;}).length;
    return '<button class="tab'+(S.place===p?" on":"")+'" data-place="'+p+'">'+(p==="all"?"All":'<span class="g" style="color:#8ea3b5;margin-right:4px">'+PLACE_GLYPH[p]+'</span>'+PLACE_LBL[p])+'<span class="n">'+n+'</span></button>'; }).join("");
  var list=here.filter(function(g){ return S.place==="all"||g.place===S.place; });
  list.sort(function(a,b){ return (b.status==="open")-(a.status==="open") || b.maxSev-a.maxSev || String(b.invoice_d).localeCompare(String(a.invoice_d)); });
  var cards=list.length?list.map(cardHtml).join(""):'<div class="empty" style="grid-column:1/-1">'+(S.all?"No errors here in this window.":"All errors is off. Only flagged errors show.")+'</div>';
  return '<div class="right"><div class="pane" style="flex:none">'+head+chart+'</div>'+
    '<div class="pane" style="flex:none"><div class="pane-h"><b>Errors</b><span class="sub">grouped by bill and code</span><span class="spacer"></span><div class="tabs">'+chips+'</div></div><div class="cards">'+cards+'</div></div></div>';
}

function cardHtml(g){
  var cls=g.status==="ack"||g.status==="res"?" ack":(g.status==="flag"?" flag":" sev-"+sevKey(g.maxSev));
  return '<div class="card'+cls+'" data-pop="'+esc(g.key)+'"><div class="c1"><span class="num">'+g.code+'</span>'+placeChip(g.place)+statusChip(g)+
    '<span class="sev"><i style="background:'+sevCol(g.maxSev)+'"></i>'+g.maxSev+'</span>'+
    (g.rows.length>1?'<span class="chip">'+g.rows.length+' blocks</span>':'')+'</div><div class="c2">'+esc(codeName(g))+'</div>'+
    '<div class="c3">Bill '+esc(g.bill_id||"—")+' · invoice '+esc(fmtD(day(g.invoice_d)))+' · '+esc(g.account||"")+'</div></div>';
}
function statusChip(g){ var m={open:["st-open","Open"],ack:["st-ack","Acknowledged"],flag:["st-flag","Flagged"],res:["st-res","Resolved"]}[g.status]; return '<span class="chip '+m[0]+'">'+m[1]+'</span>'; }

function chartHtml(its,here){
  var comms=commodities(its);
  var ctabs=comms.map(function(c){ var n=here.filter(function(g){ return g.rows.some(function(r){ return String((r._d||{}).commodity||"").toUpperCase()===c; }); }).length;
    return '<button class="tab'+(S.commodity===c?" on":"")+'" data-comm="'+esc(c)+'">'+esc(c)+(n?'<span class="n">'+n+'</span>':'')+'</button>'; }).join("");
  var pts=series(its), u=S.unit;
  var utabs=UNITS.map(function(x){ var n=here.filter(function(g){ return CHART_UNIT[g.code]===x[0]; }).length;
    return '<button class="tab'+(u===x[0]?" on":"")+'" data-unit="'+x[0]+'">'+x[1]+(n?'<span class="n">'+n+'</span>':'')+'</button>'; }).join("");
  var W=Math.max(420,(document.getElementById("root").clientWidth||1000)*0.6-60), H=230, L=62, R=14, T=12, B=26, LANE=34;
  var now=Date.now(), from=now-(Number(M.months)||12)*30.44*DAY;
  var inWin=pts.filter(function(p){ return p.e>=from; });
  var x0=Math.min(from, inWin.length?inWin[0].s:from), x1=now;
  var X=function(t){ return L+(t-x0)/(x1-x0)*(W-L-R); };
  var vals=inWin.map(function(p){ return p.v[u]; }).filter(function(v){ return v!=null; });
  var ymax=vals.length?Math.max.apply(null,vals)*1.12:1; if(!(ymax>0)) ymax=1;
  var Y=function(v){ return T+(1-v/ymax)*(H-T-B); };
  var uom=(inWin.filter(function(p){return p.uom;})[0]||{}).uom||"";
  var svg='<svg width="'+W+'" height="'+(H+LANE+18)+'">';
  for(var k=0;k<=4;k++){ var yv=ymax*k/4, yy=Y(yv); svg+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+yy+'" y2="'+yy+'" stroke="#1f3346"/><text x="'+(L-6)+'" y="'+(yy+4)+'" text-anchor="end">'+esc(shortV(yv,u))+'</text>'; }
  var d0=new Date(x0); for(var mth=new Date(Date.UTC(d0.getUTCFullYear(),d0.getUTCMonth()+1,1)).getTime(); mth<x1; ){ var dm=new Date(mth); if(dm.getUTCMonth()%3===0) svg+='<text x="'+X(mth)+'" y="'+(H-8)+'" text-anchor="middle">'+["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][dm.getUTCMonth()]+" "+String(dm.getUTCFullYear()).slice(2)+'</text>'; mth=Date.UTC(dm.getUTCFullYear(),dm.getUTCMonth()+1,1); }
  // error lookup per point
  var chartGs=here.filter(function(g){ return g.place==="chart"; });
  var marks=inWin.map(function(p){ return chartGs.filter(function(g){ return p.records[g.record_id]; }); });
  // bands first, then line, then points
  inWin.forEach(function(p,i){
    var on=marks[i].filter(function(g){ return CHART_UNIT[g.code]===u; });
    if(on.length) svg+='<rect x="'+X(Math.max(p.s,x0))+'" y="'+T+'" width="'+Math.max(3,X(p.e)-X(Math.max(p.s,x0))-2)+'" height="'+(H-T-B)+'" fill="'+COL.band+'" fill-opacity=".06"/>';
  });
  var path=""; inWin.forEach(function(p){ var v=p.v[u]; if(v==null) return; path+=(path?"L":"M")+X(p.m).toFixed(1)+","+Y(v).toFixed(1); });
  if(path) svg+='<path d="'+path+'" fill="none" stroke="'+COL.line+'" stroke-width="2"/>';
  inWin.forEach(function(p,i){
    var v=p.v[u], on=marks[i].filter(function(g){ return CHART_UNIT[g.code]===u; }), off=marks[i].filter(function(g){ return CHART_UNIT[g.code]!==u; });
    var pv=p.prior?p.prior.v[u]:null, pct=(v!=null&&pv)?((v-pv)/Math.abs(pv)*100):null;
    var base="Bill "+(p.bill_id||"—")+"  ·  "+fmtD(p.s)+" – "+fmtD(p.e)+"\n"+UNITS.filter(function(x){return x[0]===u;})[0][1]+": "+fmtV(v,u,p.uom)+(pv!=null?"\nPrior bill: "+fmtV(pv,u,p.prior.uom)+(pct!=null?"  ("+(pct>=0?"+":"")+pct.toFixed(0)+"%)":""):"");
    if(v!=null){
      if(on.length){
        if(p.prior&&pv!=null) svg+='<circle cx="'+X(p.prior.m)+'" cy="'+Y(pv)+'" r="7" fill="none" stroke="'+COL.prior+'" stroke-dasharray="3 2"/>';
        var tip=base+"\n\n"+on.map(function(g){ return g.code+"  "+codeName(g)+"  ["+g.status+"]"; }).join("\n")+"\nClick to review";
        var ms=Math.max.apply(null,on.map(function(g){return g.maxSev;}));
        svg+='<circle class="hot" cx="'+X(p.m)+'" cy="'+Y(v)+'" r="6" fill="'+sevCol(ms)+'" stroke="#132230" stroke-width="2" data-pop="'+esc(on.map(function(g){return g.key;}).join(","))+'" data-tip="'+esc(tip)+'"/>';
      } else svg+='<circle cx="'+X(p.m)+'" cy="'+Y(v)+'" r="3.5" fill="'+COL.line+'" data-tip="'+esc(base)+'"/>';
    }
    if(off.length) svg+='<rect class="hot" x="'+(X(p.m)-2)+'" y="'+(H-B)+'" width="4" height="7" fill="'+sevCol(Math.max.apply(null,off.map(function(g){return g.maxSev;})))+'" fill-opacity=".7" data-pop="'+esc(off.map(function(g){return g.key;}).join(","))+'" data-tip="'+esc(off.map(function(g){ return g.code+"  "+codeName(g)+"  (switch to "+UNITS.filter(function(x){return x[0]===CHART_UNIT[g.code];})[0][1]+")"; }).join("\n"))+'"/>';
  });
  // timeline lane
  var ly=H+6;
  svg+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+(ly+LANE/2)+'" y2="'+(ly+LANE/2)+'" stroke="#1f3346"/><text x="'+(L-6)+'" y="'+(ly+LANE/2+4)+'" text-anchor="end">Dates</text>';
  var commIts=its.filter(function(i){ return i.comm===S.commodity; });
  var lost=0;
  here.filter(function(g){ return g.place==="timeline"; }).forEach(function(g){
    var r=timelineRange(g,commIts); if(!r){ lost++; return; }
    if(r.e<x0) return;
    var warn=g.code===3009||g.code===3011;
    var xa=X(Math.max(r.s,x0)), xb=X(r.e+DAY);
    var tip=g.code+"  "+codeName(g)+"  (severity "+g.maxSev+")\n"+fmtD(r.s)+" – "+fmtD(r.e)+"  ("+Math.round((r.e-r.s)/DAY+1)+" days, "+r.how+")"+
      (r.before?"\nBefore: bill "+(r.before.bill_id||"—")+"  "+fmtD(r.before.s)+" – "+fmtD(r.before.e):"")+
      (r.after&&r.after!==r.before?"\nAfter: bill "+(r.after.bill_id||"—")+"  "+fmtD(r.after.s)+" – "+fmtD(r.after.e):"")+"\nClick to review";
    svg+='<rect class="hot" x="'+xa+'" y="'+(ly+8)+'" width="'+Math.max(4,xb-xa)+'" height="'+(LANE-16)+'" rx="3" fill="'+(g.status==="flag"?COL.flag:(warn?COL.sev.w:sevCol(g.maxSev)))+'" fill-opacity="'+(g.status==="open"||g.status==="flag"?".85":".3")+'" data-pop="'+esc(g.key)+'" data-tip="'+esc(tip)+'"/>';
  });
  svg+='</svg>';
  var noData=vals.length?"":'<div class="empty" style="padding:6px">No '+esc(UNITS.filter(function(x){return x[0]===u;})[0][1].toLowerCase())+' values on these bills'+(u==="demand"||u==="lf"?" (no matching calculation found)":"")+'.</div>';
  return '<div class="chartbox"><div class="tabs" style="margin-bottom:6px">'+ctabs+'<span class="spacer" style="flex:1"></span>'+utabs+'</div>'+svg+noData+'</div>'+
    '<div class="leg"><span><i style="background:'+COL.line+'"></i>'+esc(S.commodity||"")+' '+esc(uom)+' per bill</span><span><i style="background:rgba(231,238,244,.14)"></i>Bill with an error</span><span><i style="border:1px dashed '+COL.prior+'"></i>Prior bill</span>'+
    '<span><i style="background:'+COL.sev.c+';border-radius:50%"></i>Severity \u226560</span><span><i style="background:'+COL.sev.s+';border-radius:50%"></i>40\u201359</span><span><i style="background:'+COL.sev.w+';border-radius:50%"></i>Below 40 / warning</span><span><i style="background:'+COL.flag+'"></i>Flagged</span>'+(lost?'<span>'+lost+' date error(s) not on this commodity</span>':'')+'</div>';
}
function shortV(v,u){ if(u==="$") return "$"+(v>=1e6?(v/1e6).toFixed(1)+"M":v>=1e3?(v/1e3).toFixed(0)+"k":v.toFixed(0)); if(u==="unit") return "$"+v.toFixed(3); if(u==="lf") return (v>1.5?v.toFixed(0):(v*100).toFixed(0))+"%"; return v>=1e6?(v/1e6).toFixed(1)+"M":v>=1e3?(v/1e3).toFixed(0)+"k":v.toFixed(0); }

function popupHtml(gs){
  if(!S.popup) return "";
  var keys=S.popup, list=gs.filter(function(g){ return keys.indexOf(g.key)>=0; });
  if(!list.length){ S.popup=null; return ""; }
  var its=items();
  var body=list.map(function(g){
    var todo=TODO[g.code]||"either";
    var msgs={}; g.rows.forEach(function(r){ if(r.message) msgs[r.message]=true; });
    var ml=Object.keys(msgs);
    var kv=[["Stage",stageLbl(g.stage)],["Severity",g.rows.map(function(r){return r.severity;}).filter(function(v,i,a){return a.indexOf(v)===i;}).join(", ")],
      ["Bill",(g.bill_id||"—")+"  ·  invoice "+fmtD(day(g.invoice_d))],["Account",g.account||"—"],["Vendor",g.vendor||"—"]];
    var d=(g.rows[0]&&g.rows[0]._d)||{};
    if(d.commodity) kv.push(["Utility",d.commodity]);
    if(Object.keys(g.meters).length) kv.push(["Meter",Object.keys(g.meters).join(", ")]);
    var mine=its.filter(function(i){ return String(i.record)===String(g.record_id); });
    if(mine.length){ var s=Math.min.apply(null,mine.map(function(i){return i.s;})), e=Math.max.apply(null,mine.map(function(i){return i.e||i.s;})); kv.push(["Service period",fmtD(s)+" – "+fmtD(e)]); }
    if(g.place==="chart"){
      var u=CHART_UNIT[g.code], saveC=S.commodity, cm=(mine[0]||{}).comm; if(cm) S.commodity=cm;
      var p=series(its).filter(function(p){ return p.records[g.record_id]; })[0]; S.commodity=saveC;
      if(p){ var v=p.v[u], pv=p.prior?p.prior.v[u]:null; kv.push(["This bill",fmtV(v,u,p.uom)]); kv.push(["Prior bill",pv!=null?fmtV(pv,u,p.prior.uom)+"  (bill "+(p.prior.bill_id||"—")+")":"—"]); if(v!=null&&pv) kv.push(["Change",((v-pv)/Math.abs(pv)*100).toFixed(1)+"%"]); }
      kv.push(["Threshold","Not available yet (per-customer source not located)"]);
    }
    if(g.place==="timeline"){
      var r=timelineRange(g,its);
      if(r){ kv.push(["Affected dates",fmtD(r.s)+" – "+fmtD(r.e)+"  ("+Math.round((r.e-r.s)/DAY+1)+" days, "+r.how+")"]); if(r.before&&r.before!==r.after) kv.push(["Bill before",(r.before.bill_id||"—")+"  "+fmtD(r.before.s)+" – "+fmtD(r.before.e)]); if(r.after) kv.push(["Bill after",(r.after.bill_id||"—")+"  "+fmtD(r.after.s)+" – "+fmtD(r.after.e)]); }
    }
    if(g.place==="dot"){ var ent={meter:d.meter_serial||"—",account:d.account_code||g.account||"—"}[DOT[g.code]]; kv.push([DOT[g.code]==="meter"?"New meter / account":"Account",ent]); if(g.code===3007) kv.push(["Vendor code",g.vendor||"—"]); }
    var hist=['Raised '+esc(fmtD(day(g.rows[0].raised)))+(g.rows.length>1?" ("+g.rows.length+" bill blocks)":"")].concat((S.log[g.key]||[]).map(esc));
    var ackBtn='<button class="btn'+(todo==="accept"?" pri":"")+'" data-act="ack" data-g="'+esc(g.key)+'">Acknowledge</button>';
    var flagBtn='<button class="btn flag'+(todo==="escalate"?" pri":"")+'" data-act="flag" data-g="'+esc(g.key)+'">Flag to operator</button>';
    var acts;
    if(g.status==="res") acts='<span class="chip st-res">Resolved in UBM</span>';
    else if(g.status==="ack") acts='<button class="btn pri" data-act="reflag" data-g="'+esc(g.key)+'">Re-flag</button>';
    else if(g.status==="flag") acts='<span class="chip st-flag">With operator</span>';
    else acts=ackBtn+flagBtn;
    var draft=S.flagDraft===g.key?'<div><textarea id="flagnote" placeholder="Note for the operator (optional)"></textarea><div class="acts"><button class="btn flag pri" data-act="flagok" data-g="'+esc(g.key)+'">Send flag</button><button class="btn" data-act="flagcancel">Cancel</button></div></div>':"";
    return '<div class="grp"><div class="gh"><b>'+g.code+' · '+esc(codeName(g))+'</b>'+statusChip(g)+placeChip(g.place)+'<span class="sev"><i style="background:'+sevCol(g.maxSev)+'"></i>Severity '+g.maxSev+'</span><span class="chip">Default: '+({accept:"Accept",escalate:"Escalate",either:"Either"}[todo])+'</span></div>'+
      '<div class="kv">'+kv.map(function(x){ return '<span>'+esc(x[0])+'</span><span class="num">'+esc(x[1])+'</span>'; }).join("")+'</div>'+
      (ml.length?'<ul class="msgs">'+ml.slice(0,5).map(function(m){return '<li>'+esc(m)+'</li>';}).join("")+(ml.length>5?'<li>+'+(ml.length-5)+' more</li>':'')+'</ul>':'')+
      '<ul class="hist">'+hist.map(function(h){return '<li>'+h+'</li>';}).join("")+'</ul>'+
      '<div class="acts">'+acts+(g.bill_id?'<span class="spacer" style="flex:1"></span><button class="btn link" data-open="'+esc(g.bill_id)+'">Open bill '+esc(g.bill_id)+'</button>':'')+'</div>'+draft+'</div>';
  }).join("");
  return '<div class="ov" id="ov"><div class="modal"><div class="mh"><b>'+(list.length===1?"Validation error":list.length+" validation errors")+'</b><button class="x" id="closepop">×</button></div>'+
    '<div class="mb"><div class="note">Prototype: Acknowledge and Flag are kept in this browser tab only and are not saved to UBM.</div>'+body+'</div></div></div>';
}

// ---- actions ---------------------------------------------------------------------
function findGroup(key){ return groups().filter(function(g){ return g.key===key; })[0]; }
function stamp(){ var d=new Date(); return (d.getMonth()+1)+"/"+d.getDate()+" "+d.toTimeString().slice(0,5); }
function act(kind,key){
  var g=findGroup(key); if(!g) return;
  var log=S.log[key]||(S.log[key]=[]);
  if(kind==="ack"){ g.ids.forEach(function(i){ S.ack[i]=true; }); log.push("Acknowledged (muted) "+stamp()+" · not saved"); }
  if(kind==="reflag"){ g.ids.forEach(function(i){ delete S.ack[i]; }); log.push("Re-flagged "+stamp()+" · not saved"); }
  if(kind==="flag"){ S.flagDraft=key; }
  if(kind==="flagok"){ var n=(document.getElementById("flagnote")||{}).value||""; g.ids.forEach(function(i){ S.flag[i]=true; delete S.ack[i]; }); log.push("Flagged to operator "+stamp()+(n?": “"+n+"”":"")+" · not saved"); S.flagDraft=null; }
  if(kind==="flagcancel"){ S.flagDraft=null; }
  render();
}

function bind(){
  var $=function(id){ return document.getElementById(id); };
  var c=$("cust"); if(c) c.onchange=function(){ S.sel=null; S.expanded={}; S.popup=null; send("onPickCustomer",{pickedCustomer:Number(c.value)||0}); };
  var mo=$("months"); if(mo) mo.onchange=function(){ send("onPickMonths",{pickedMonths:Number(mo.value)||12}); };
  var al=$("all"); if(al) al.onclick=function(){ S.all=!S.all; render(); };
  var mu=$("muted"); if(mu) mu.onclick=function(){ S.muted=!S.muted; render(); };
  var q=$("q"); if(q) q.oninput=function(){ S.q=q.value; render(); var nq=$("q"); if(nq){ nq.focus(); nq.setSelectionRange(nq.value.length,nq.value.length); } };
  var cs=$("clearsel"); if(cs) cs.onclick=function(){ S.sel=null; render(); };
  var cp=$("closepop"); if(cp) cp.onclick=function(){ S.popup=null; S.flagDraft=null; render(); };
  var ov=$("ov"); if(ov) ov.onclick=function(e){ if(e.target===ov){ S.popup=null; S.flagDraft=null; render(); } };
  var root=document.getElementById("root");
  root.onclick=function(e){
    var t=e.target;
    var pop=t.closest&&t.closest("[data-pop]"); if(pop){ e.stopPropagation(); S.popup=pop.getAttribute("data-pop").split(","); S.flagDraft=null; render(); return; }
    var a=t.closest&&t.closest("[data-act]"); if(a){ act(a.getAttribute("data-act"),a.getAttribute("data-g")); return; }
    var ob=t.closest&&t.closest("[data-open]"); if(ob){ send("onOpenBill",{pickedBill:ob.getAttribute("data-open")}); return; }
    var ex=t.closest&&t.closest("[data-exp]"); if(ex){ var k=ex.getAttribute("data-exp"); S.expanded[k]=!S.expanded[k]; render(); return; }
    var lo=t.closest&&t.closest("[data-loc]"); if(lo){ var id=lo.getAttribute("data-loc");
      if(String(M.locationId)===id){ if(S.sel){ S.sel=null; render(); } return; }
      S.sel=null; S.expanded={}; S.place="all"; send("onPickLocation",{pickedLocation:Number(id)}); return; }
    var ac=t.closest&&t.closest("[data-acct]"); if(ac){ var key=ac.getAttribute("data-acct"); S.sel={kind:"acct",acct:key}; S.expanded[key]=true; render(); return; }
    var va=t.closest&&t.closest("[data-va]"); if(va){ var lbl=(va.querySelector(".t")||{}).textContent; S.sel={kind:"meter",va:va.getAttribute("data-va"),acct:va.getAttribute("data-acctof"),label:lbl}; render(); return; }
    var cm=t.closest&&t.closest("[data-comm]"); if(cm){ S.commodity=cm.getAttribute("data-comm"); render(); return; }
    var un=t.closest&&t.closest("[data-unit]"); if(un){ S.unit=un.getAttribute("data-unit"); render(); return; }
    var pl=t.closest&&t.closest("[data-place]"); if(pl){ S.place=pl.getAttribute("data-place"); render(); return; }
  };
}

// ---- tooltip + model polling ------------------------------------------------------
var tt=document.createElement("div"); tt.className="tt"; document.body.appendChild(tt);
document.addEventListener("mousemove",function(e){
  var el=(e.target&&e.target.closest)?e.target.closest("[data-tip]"):null;
  if(el){ tt.textContent=el.getAttribute("data-tip"); tt.style.opacity="1"; var tw=tt.offsetWidth, th=tt.offsetHeight, tx=e.clientX+14, ty=e.clientY+16;
    if(tx+tw>window.innerWidth-8) tx=e.clientX-14-tw; if(tx<8) tx=8; if(ty+th>window.innerHeight-8) ty=e.clientY-12-th; if(ty<8) ty=8;
    tt.style.left=tx+"px"; tt.style.top=ty+"px"; }
  else tt.style.opacity="0";
});
var lastW=0;
function tick(){
  try{
    var m=(window.appsmith&&appsmith.model)||{};
    var s=JSON.stringify(m);
    var w=(document.getElementById("root")||{}).clientWidth||0;
    if(s!==lastModel||Math.abs(w-lastW)>20){ lastModel=s; lastW=w; M=m; render(); }
  }catch(e){}
}
tick(); setInterval(tick,400);
